import { NextRequest, NextResponse } from "next/server";
import { youtubeDl } from "youtube-dl-exec";

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const title = searchParams.get("title");
    const artist = searchParams.get("artist");

    if (!title || !artist) {
      return NextResponse.json(
        { error: "Missing required parameters: 'title' and 'artist'" },
        { status: 400 }
      );
    }

    // Исправлено: убран перенос строки, теперь это корректный цельный поисковый запрос
    const searchQuery = `ytsearch1:${artist} ${title} audio`;

    try {
      // Используем getUrl, чтобы получить только чистую ссылку без парсинга сложных JSON
      const audioUrl = await youtubeDl(searchQuery, {
        getUrl: true,
        format: "bestaudio/best",
        noWarnings: true,
        noCallHome: true,
        noCheckCertificates: true, // Помогает обойти некоторые блокировки
      } as any);
      

      if (!audioUrl || typeof audioUrl !== "string") {
        throw new Error("Invalid URL returned from yt-dlp");
      }

      return NextResponse.json(
        {
          // youtubeDl возвращает строку с ссылкой, очищаем ее от возможных пробелов и \n в конце
          url: audioUrl.trim(),
          title: title,
        },
        { status: 200 }
      );
      
    } catch (youtubeError) {
      console.error("YouTube-dl error:", youtubeError);
      
      return NextResponse.json(
        {
          error: "Failed to retrieve audio from YouTube",
          details: youtubeError instanceof Error ? youtubeError.message : "Unknown error",
        },
        { status: 500 }
      );
    }
  } catch (error) {
    console.error("Audio API error:", error);

    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}